changeSet.sql:
UPDATE conversation
SET participant_pair_key = (
    SELECT CONCAT(MIN(participant.user_id), '-', MAX(participant.user_id))
    FROM conversation_participant participant
    WHERE participant.conversation_id = conversation.id
    HAVING COUNT(*) = 2
)
WHERE discriminator = 'O';

DROP TABLE IF EXISTS tmp_one_to_one_chat_duplicate;

INSERT INTO tmp_one_to_one_chat_duplicate (duplicate_id, keep_id, last_message_date) SELECT dup.id, oldest.keep_id, dup.last_message_date FROM conversation dup JOIN ( SELECT course_id, participant_pair_key, MIN(id) AS keep_id FROM conversation WHERE participant_pair_key IS NOT NULL GROUP BY course_id, participant_pair_key HAVING COUNT(*) > 1 ) oldest ON oldest.course_id = dup.course_id AND oldest.participant_pair_key = dup.participant_pair_key WHERE dup.id <> oldest.keep_id;
UPDATE post SET conversation_id = (SELECT merged.keep_id FROM tmp_one_to_one_chat_duplicate merged WHERE merged.duplicate_id = post.conversation_id) WHERE conversation_id IN (SELECT duplicate_id FROM tmp_one_to_one_chat_duplicate);
UPDATE conversation SET last_message_date = (SELECT MAX(merged.last_message_date) FROM tmp_one_to_one_chat_duplicate merged WHERE merged.keep_id = conversation.id) WHERE id IN (SELECT keep_id FROM tmp_one_to_one_chat_duplicate) AND (last_message_date IS NULL OR last_message_date < (SELECT MAX(merged.last_message_date) FROM tmp_one_to_one_chat_duplicate merged WHERE merged.keep_id = conversation.id));
DELETE FROM conversation_participant WHERE conversation_id IN (SELECT duplicate_id FROM tmp_one_to_one_chat_duplicate);
DELETE FROM conversation WHERE id IN (SELECT duplicate_id FROM tmp_one_to_one_chat_duplicate);
